from typing import List

class Solution:
    def sortArrayByParity(self, nums: List[int]) -> List[int]:
        lo, hi = 0, len(nums) - 1
        while lo < hi:
            if nums[lo] % 2 > nums[hi] % 2:
                nums[lo], nums[hi] = nums[hi], nums[lo]
            if nums[lo] % 2 == 0:
                lo += 1
            if nums[hi] % 2 == 1:
                hi -= 1
        return nums

class Solution {
public:
    vector<int> sortArrayByParity(vector<int>& nums) {
        int lo = 0, hi = (int)nums.size() - 1;
        while (lo < hi) {
            if (nums[lo] % 2 > nums[hi] % 2) {
                swap(nums[lo], nums[hi]);
            }
            if (nums[lo] % 2 == 0) lo++;
            if (nums[hi] % 2 == 1) hi--;
        }
        return nums;
    }
};

class Solution {
    public int[] sortArrayByParity(int[] nums) {
        int lo = 0, hi = nums.length - 1;
        while (lo < hi) {
            if (nums[lo] % 2 > nums[hi] % 2) {
                int tmp = nums[lo];
                nums[lo] = nums[hi];
                nums[hi] = tmp;
            }
            if (nums[lo] % 2 == 0) lo++;
            if (nums[hi] % 2 == 1) hi--;
        }
        return nums;
    }
}

var sortArrayByParity = function(nums) {
    let lo = 0, hi = nums.length - 1;
    while (lo < hi) {
        if (nums[lo] % 2 > nums[hi] % 2) {
            const tmp = nums[lo];
            nums[lo] = nums[hi];
            nums[hi] = tmp;
        }
        if (nums[lo] % 2 === 0) lo++;
        if (nums[hi] % 2 === 1) hi--;
    }
    return nums;
};
